    @Test func quarterVectorResizingFromUInt8ThroughPair() {
        let mismatches = Mismatches(
            "quarterVectorResizingFromUInt8 through GenericAnySourcePair<Float16, UInt8>"
        )
        let aInputs = Inputs.conversions(SIMD<UInt8>.self, seed: 0x0FA5_B733_4961_F39F)
        for a in aInputs {
            let port = GenericAnySourcePair<Float16, UInt8>.quarterVector(resizing: a)
            let reference = H.quarterVector(resizing: a)
            let definedBytes = SIMD<UInt8>.laneCount * MemoryLayout<UInt8>.stride
            let grownBytes = H.QuarterVector.laneCount * MemoryLayout<Lane>.stride
            let newBytes = HighwayReference.resizedBytesDefined(
                definedBytes,
                grownBytes,
                definedBytes
            )
            mismatches.check(
                Array(bytes(of: port).prefix(definedBytes)),
                Array(bytes(of: reference).prefix(definedBytes)),
                "a: \(describe(a))"
            )
            mismatches.check(
                Array(registerBytes(of: port).dropFirst(definedBytes).prefix(newBytes)),
                Array(registerBytes(of: reference).dropFirst(definedBytes).prefix(newBytes)),
                "a: \(describe(a))"
            )
        }
        mismatches.record()
    }

